const config=window.OWAYS;const $=s=>document.querySelector(s);const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#subscriptions-grid').innerHTML=config.subscriptions.map((p,i)=>`<article class="product ${i===0?'featured':''}">${i===0?'<span class="product-badge">للإنتاجية والإبداع</span>':''}<div class="product-icon" style="background:${p.color}">${safe(p.icon)}</div><h3 dir="ltr">${safe(p.name)}</h3><p>${safe(p.desc)}</p><div class="price">${p.price===null?'حسب الخطة':safe(p.price)+' '+safe(config.currency)}<small>تفاصيل السعر عند الطلب</small></div><ul>${p.features.map(f=>`<li>${safe(f)}</li>`).join('')}</ul><button class="button" data-add="${p.id}">طلب الاشتراك <span>＋</span></button></article>`).join('');
$('#web-grid').innerHTML=config.web.map((p,i)=>`<article class="web-card"><div class="web-preview"><div class="browser-dots">● ● ●</div><div class="mock-body"><div style="${i===1?'flex:2':i===2?'background:linear-gradient(90deg,#59baff44 30%,transparent 30%,transparent 35%,#59baff44 35%,#59baff44 65%,transparent 65%,transparent 70%,#59baff44 70%)':''}"></div><span><i></i><i></i><i></i></span></div></div><h3>${safe(p.name)}</h3><p>${safe(p.desc)}</p><ul>${p.features.map(f=>`<li>${safe(f)}</li>`).join('')}</ul><button class="button outline" data-add="${p.id}">اطلب عرض سعر ←</button></article>`).join('');
let cart=[];try{const saved=JSON.parse(localStorage.getItem('oways-cart')||'[]');if(Array.isArray(saved))cart=saved.filter(id=>[...config.subscriptions,...config.web].some(p=>p.id===id));}catch{}function refresh(){const items=cart.map(id=>[...config.subscriptions,...config.web].find(p=>p.id===id));$('#count').textContent=items.length;$('#cart-items').innerHTML=items.length?items.map(p=>`<div class="cart-item"><div>${safe(p.name)}<small>${p.price!=null?safe(p.price)+' '+safe(config.currency):'السعر يُحدَّد بعد مراجعة الطلب'}</small></div><button data-remove="${p.id}" aria-label="حذف ${safe(p.name)}">حذف</button></div>`).join(''):'<p>سلتك فارغة. اكتشف الخدمات وأضف ما يناسبك.</p>';$('#checkout').disabled=!items.length;$('#total').textContent=items.length?'تُؤكَّد التكلفة النهائية قبل الشراء.':'';try{localStorage.setItem('oways-cart',JSON.stringify(cart))}catch{}}refresh();let timer;function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',2500)}
function contact(msg){if(/^\d{8,15}$/.test(config.whatsapp)){window.open('https://wa.me/'+config.whatsapp+'?text='+encodeURIComponent(msg),'_blank','noopener,noreferrer')}else{$('#message').value=msg;$('#copy-status').textContent='';$('#contact').showModal()}}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){if(!cart.includes(add.dataset.add)){cart.push(add.dataset.add);refresh();toast('أُضيفت الخدمة إلى السلة')}else toast('الخدمة موجودة في السلة')}const remove=e.target.closest('[data-remove]');if(remove){cart=cart.filter(id=>id!==remove.dataset.remove);refresh()}const close=e.target.closest('[data-close]');if(close)$('#'+close.dataset.close).close();const c=e.target.closest('[data-contact]');if(c)contact(c.dataset.contact)});$('.cart-toggle').onclick=()=>$('#cart').showModal();$('#menu').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open)};document.querySelectorAll('nav a').forEach(a=>a.onclick=()=>{$('#navigation').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')});$('#checkout').onclick=()=>{$('#cart').close();contact('مرحبًا أويس تك، أرغب في طلب الخدمات التالية:\n'+cart.map(id=>[...config.subscriptions,...config.web].find(p=>p.id===id).name).join('\n')+'\nيرجى إرسال الأسعار والمدة وتفاصيل التفعيل والتنفيذ.')};$('#renew-form').onsubmit=e=>{e.preventDefault();if(!$('#reference').value.trim())return;contact('أرغب في تجديد اشتراك '+$('#service').value+'\nبيانات الطلب السابق: '+$('#reference').value.trim())};$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#message').value);$('#copy-status').textContent='تم نسخ الرسالة.'}catch{$('#message').select();$('#copy-status').textContent='حدّد النص وانسخه يدويًا.'}};$('#year').textContent=new Date().getFullYear();document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
